sp_widget.client_script:
function($scope) {
  var c = this;
  c.message = 'Initializing...';
  const MODEL_URL = 'https://justadudewhohacks.github.io/face-api.js/models';

  // Start webcam stream
  async function startVideo() {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      document.getElementById('video').srcObject = stream;
    } catch (e) {
      throw 'Camera access denied or unavailable';
    }
  }

  c.$onInit = function() {
    // Dynamically load face-api.js
    $.getScript('https://cdn.jsdelivr.net/npm/face-api.js@0.22.2/dist/face-api.min.js')
      .done(async function() {
        if (!window.faceapi) {
          c.message = 'Error: face-api.js did not load.';
          return;
        }
        try {
          // Load models
          await faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL);
          await faceapi.nets.faceLandmark68Net.loadFromUri(MODEL_URL);
          await faceapi.nets.faceRecognitionNet.loadFromUri(MODEL_URL);
          // Start camera
          await startVideo();
          c.message = 'Ready. Click Verify Face';
        } catch (err) {
          console.error(err);
          c.message = 'Error: ' + err;
        }
        $scope.$applyAsync();
      })
      .fail(function() {
        c.message = 'Error loading face-api.js';
        $scope.$applyAsync();
      });
  };

  c.verifyFace = async function() {
    c.message = 'Scanning...';
    $scope.$applyAsync();
    try {
      // Load reference descriptors
      const labeledDescriptors = await Promise.all(
        c.data.labels.map(async label => {
          const img = await faceapi.fetchImage(c.data.imageUrls[label]);
          const detection = await faceapi.detectSingleFace(img, new faceapi.TinyFaceDetectorOptions())
            .withFaceLandmarks().withFaceDescriptor();
          return new faceapi.LabeledFaceDescriptors(label, [detection.descriptor]);
        })
      );
      const matcher = new faceapi.FaceMatcher(labeledDescriptors, 0.5);
      // Detect from live video
      const result = await faceapi.detectSingleFace(document.getElementById('video'), new faceapi.TinyFaceDetectorOptions())
        .withFaceLandmarks().withFaceDescriptor();
      if (!result) {
        c.message = 'No face detected';
      } else {
        const bestMatch = matcher.findBestMatch(result.descriptor);
        c.message = (bestMatch.label !== 'unknown') ? '✅ Welcome ' + bestMatch.label : '❌ Face not recognized';
      }
    } catch (err) {
      console.error(err);
      c.message = 'Error: ' + err;
    }
    $scope.$applyAsync();
  };
}

sp_widget.script:
(function() {
  // Ensure this matches your uploaded image name under Service Portal > Images
  data.labels = ['UserFace'];
  data.imageUrls = { 'UserFace': 'https://dev182388.service-now.com/api/now/ui/image?sysparm_image_name=x_58872_needit.user_face.jpg' };
